 const goTo=i=>{HI=i;GB=true;try{showView(HIST[i])}finally{GB=false}return true};
 const goBackOne=()=>HI>0?goTo(HI-1):false;
 const goFwd=()=>HI<HIST.length-1?goTo(HI+1):false;
 function shut(){HIST=[];HI=-1;document.querySelectorAll('.view').forEach(v=>v.hidden=true);document.querySelectorAll('.nb').forEach(b=>b.classList.remove('on'));apply()}
