 setInterval(sync,600);
 bk.onclick=()=>{try{const c=cur();if(c==='exam'&&window.__exBack&&window.__exBack())return;if(c==='etimer'){showView('exam');return}if(goBackOne())return}catch(e){}close()};cl.onclick=close;back.onclick=close;pv.onclick=()=>step(-1);nx.onclick=()=>step(1);
 addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('ov')){const m=document.getElementById('sm'),c=document.getElementById('calm');if((m&&m.style.display==='flex')||(c&&c.classList.contains('on')))return;close()}});
