const rng=(p,s)=>p+(s>1?'–'+(p+s-1):'');
function verdict(n,r){
 const d=dayIdx(r.date),sp=spanOf(r),tv=tm({c:r.cls||'',d,p:r.per,s:sp});
 if(n===r.absent)return{cls:'bad',msg:'⛔ Cannot assign — this is the absent teacher.'};
 if(absentOn(n,r.date,r))return{cls:'bad',msg:'⛔ Cannot assign — '+n+' is recorded absent on the same day.'};
 const c=conflictOf(n,r.date,d,r.per,sp,r);
 if(c){if(c.kind==='lesson'){const l=c.l;return{cls:'bad',msg:'⛔ Time conflict — '+n+' has a lesson at the same time: period '+rng(l.p,l.s)+' · '+l.c+(tm(l)?' · '+tm(l):'')+'. Lessons must not overlap.'}}
  return{cls:'bad',msg:'⛔ Time conflict — '+n+' is assigned as substitute at the same time (period '+rng(c.r.per,spanOf(c.r))+' · '+c.r.cls+' · for the absent teacher '+c.r.absent+').'}}
 const load=loadOf(n,r.date,d,r);
 if(!LD[n].length)return SUBX.includes(n)?{cls:'ok',msg:'✔ Additional staff (no timetable) — free in period '+rng(r.per,sp)+(tv?' ('+tv+')':'')+'.'}:{cls:'warn',msg:'⚠ No timetable is recorded for this teacher in the file — check availability manually.'};
 if(load+sp>5)return{cls:'warn',msg:'⚠ Available at this time, but he will then have '+(load+sp)+' lessons today (more than 5).'};
 return{cls:'ok',msg:'✔ Available in period '+rng(r.per,sp)+(tv?' ('+tv+')':'')+' — he will then have '+(load+sp)+' lessons today.'}}
const homeDept=r=>TDEPT[r.absent]||((save.myDept&&DN[save.myDept])?gOf(save.myDept):'');
const dIdx=k=>{const i=DEPTS.findIndex(z=>z[0]===k);return i<0?99:i};
function extraLs(r){const d=dayIdx(r.date);return((SM&&SM.extra)||[]).map(p=>lessonsSp(r.absent,d).find(x=>x.p===p)).filter(Boolean)}
function suggestions(r,over){
 const d=dayIdx(r.date),sp=spanOf(r),ad=homeDept(r),out=[],ex=extraLs(r),tsp=sp+ex.reduce((a,l)=>a+l.s,0);
 SUBN.forEach(n=>{const x=SUBX.includes(n);if(n===r.absent||(!LD[n].length&&!x)||absentOn(n,r.date,r))return;if(conflictOf(n,r.date,d,r.per,sp,r))return;if(ex.some(l=>conflictOf(n,r.date,d,l.p,l.s,r)))return;const ld=loadOf(n,r.date,d,r),ov=ld+tsp>5;if(ov&&!over&&!(TDEPT[n]===ad||gOf(TDEPT[n])===gOf(ad)))return;out.push({n,load:ld,same:TDEPT[n]===ad,dept:TDEPT[n],x,ov,tsp})});
 const ag=gOf(ad);out.forEach(o=>o.circ=gOf(o.dept)===ag);out.sort((a,b)=>(b.same-a.same)||(b.x-a.x)||(b.circ-a.circ)||(dIdx(a.dept)-dIdx(b.dept))||(a.ov-b.ov)||(a.load-b.load)||a.n.localeCompare(b.n));return out}
