function undoUpd(){const u=document.getElementById('exUndo'),r=document.getElementById('exRedo');if(u){u.disabled=!HI.u.length;u.title=HI.u.length?'Undo: '+HI.u[HI.u.length-1].l+' (Ctrl+Z)':'Nothing to undo'}if(r){r.disabled=!HI.r.length;r.title=HI.r.length?'Redo: '+HI.r[HI.r.length-1].l+' (Ctrl+Y)':'Nothing to redo'}}
