    const tb=el('table','bdT'),th=el('tr');['Hall | القاعة','Time | الوقت','Exam sessions | الاختبارات','Invigilators | المراقبون',''].forEach(z=>th.append(el('th','',z)));tb.append(th);let nh=0,ni=0;
