const perInv=()=>{let v=16;try{const s=+localStorage.getItem('ex_per');if(s>=5&&s<=60)v=s}catch(e){}return window.__perInv||v};
const needFor=n=>n<=0?1:Math.min(8,Math.ceil(n/perInv()));
