const HALL_CAT=[["MW12-2", "MW"], ["MW13-1", "MW"], ["MW13-2", "MW"], ["MW14-1", "MW"], ["MW14-2", "MW"], ["Airplane", "MW"], ["MW6-5", "M"], ["MW6-6", "M"], ["MW6-7", "M"], ["M5", "M"], ["M6", "M"], ["M7", "M"], ["B6", "B"], ["B5", "B"], ["B7", "B"], ["B8", "B"], ["B9", "B"], ["B17", "B"], ["B18", "B"], ["A-BLOCK", "A"], ["Canteen", "A"], ["A215", "A"], ["A216", "A"], ["A217", "A"], ["A218", "A"], ["E6, E23, E24", "E"], ["Clinic", "SC"], ["لجنة خاصة · Special Committee", "SC"], ["Gym", "OT"]];window.__hallCat=HALL_CAT;
function applyXT(){try{(S.extraT||[]).forEach(n=>{if(n&&!NAMES_EX.includes(n))NAMES_EX.push(n)})}catch(e){}}
function xtDel(n){S.extraT=(S.extraT||[]).filter(x=>x!==n);[NAMES_EX,names].forEach(A=>{const i=A.indexOf(n);if(i>=0&&A!==names)A.splice(i,1)})}
function xtUsed(n){return S.days.some(x=>Object.values(x.inv||{}).some(L=>(L||[]).includes(n)))}
function xtRen(n,nv){nv=(nv||'').trim().replace(/\s+/g,' ');if(nv.length<3)return '⚠ اكتب الاسم · enter the name';if(nv===n)return '';if(names.concat(NAMES_EX).some(x=>x.toLowerCase()===nv.toLowerCase()))return '⚠ الاسم موجود مسبقًا · already in the list';
 S.extraT=(S.extraT||[]).map(x=>x===n?nv:x);try{S.days=JSON.parse(JSON.stringify(S.days).split(JSON.stringify(n)).join(JSON.stringify(nv)))}catch(e){}
 const i=NAMES_EX.indexOf(n);if(i>=0)NAMES_EX.splice(i,1);applyXT();return ''}
