/* ===== exam times follow the final exams timetable (per grade) unless the coordinator unlocks them ===== */
function finSync(d){try{if(!d||!d.date||d.manT||!window.__finInfo)return false;const it=window.__finInfo.day(d.date);if(!it.length)return false;let ch=false;const set=(o,k,v)=>{if(o[k]!==v){o[k]=v;ch=true}};
 let a='99:99',b='00:00',allE=true;const byG={};
 it.forEach(x=>{const g=byG[x.g]=byG[x.g]||{a:'99:99',b:'00:00',e:true};x.parts.forEach(p=>{if(p[0]<a)a=p[0];if(p[1]>b)b=p[1];if(p[2]!=='E')allE=false;if(p[0]<g.a)g.a=p[0];if(p[1]>g.b)g.b=p[1];if(p[2]!=='E')g.e=false})});
 set(d,'from',a);set(d,'to',b);set(d,'type',allE?'Electronic':'Paper');
 (d.sess||[]).forEach(s=>{const g=byG[gOfCls(s.cls)];if(g){set(s,'from',g.a);set(s,'to',g.b);set(s,'ty',g.e?'Electronic':'Paper')}});
 return ch}catch(e){return false}}
const finLinked=d=>!!(d&&d.date&&!d.manT&&window.__finInfo&&window.__finInfo.day(d.date).length);
/* keep the scroll position on every redraw (changing a number, adding a name, etc.) */
{const _draw=draw;draw=function(){const keep=[];for(let e=ROOT;e;e=e.parentElement)if(e.scrollHeight>e.clientHeight)keep.push([e,e.scrollTop]);const wx=window.scrollX,wy=window.scrollY;const r=_draw.apply(this,arguments);keep.forEach(([e,t])=>{if(e.isConnected&&Math.abs(e.scrollTop-t)>1)e.scrollTop=t});if(Math.abs(window.scrollY-wy)>1)window.scrollTo(wx,wy);requestAnimationFrame(()=>keep.forEach(([e,t])=>{if(e.isConnected&&Math.abs(e.scrollTop-t)>1)e.scrollTop=t}));return r}}

/* ===== simple invigilation page for editors: day → halls → invigilators → download & save ===== */
