 const intentOf=s=>/غياب|غائب|absen|إشغال|اشغال|substitut/i.test(s)?'abs':/مشرف|supervis/i.test(s)?'sup':/مراقب[^\s]*\s*عام|عامون|عامين|controller/i.test(s)?'ctl':/مراقب|invigil/i.test(s)?'inv':/طلاب|طالب|student|roster/i.test(s)?'stu':'';
