 p.innerHTML=dlDays().map(d=>'<h2>Invigilation plan — '+esc(FMT(d.date))+'</h2><p>'+esc((d.title||'')+' · '+(d.type||'')+' · General controllers: '+(S.controllers.filter(Boolean).join(' & ')||'—'))+'</p><table><tr>'+HDR.map(x=>'<th>'+x+'</th>').join('')+'</tr>'+flat(d).map(r=>'<tr>'+r.map(x=>'<td>'+esc(x)+'</td>').join('')+'</tr>').join('')+'</table>').join('<div style="page-break-after:always"></div>');
