function myVenues(d,n){return S.venues.filter(v=>(d.inv[v.id]||[]).includes(n))}
const ENG_AR=/[؀-ۿ]/;
function engClean(s,keep){if(!ENG_AR.test(s))return s;let t=String(s).replace(/الصف\s*/g,'Grade ').replace(/\s*دقيقة/g,' min').replace(/\s*د\)/g,' min)');
 t=t.replace(/[؀-ۿݐ-ݿ][؀-ۿݐ-ݿ\s،؟٪-٬\-–—ـ]*/g,'');
 t=t.replace(/\(\s*[·|]\s*/g,'(').replace(/\s*[·|]\s*(?=[·|)›]|$)/g,'').replace(/^([^A-Za-z0-9]*?)\s*[·|—]\s+(?=[A-Za-z0-9])/,'$1 ').replace(/\s{2,}/g,' ').trim();return /[A-Za-z0-9]/.test(t)?t:(keep?s:'')}
function engDom(root,keep){try{const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const L=[];let n;while((n=w.nextNode()))if(ENG_AR.test(n.nodeValue))L.push(n);L.forEach(x=>{x.nodeValue=engClean(x.nodeValue,keep)});
 if(root.querySelectorAll)root.querySelectorAll('[placeholder],[title]').forEach(e=>{['placeholder','title'].forEach(a=>{const v=e.getAttribute(a);if(v&&ENG_AR.test(v))e.setAttribute(a,engClean(v))})})}catch(e){}}
function engWatch(root){engDom(root);try{new MutationObserver(ms=>{ms.forEach(m=>{if(m.type==='characterData'){if(ENG_AR.test(m.target.nodeValue))m.target.nodeValue=engClean(m.target.nodeValue)}else m.addedNodes.forEach(n=>{if(n.nodeType===3){if(ENG_AR.test(n.nodeValue))n.nodeValue=engClean(n.nodeValue)}else if(n.nodeType===1)engDom(n)})})}).observe(root,{childList:true,subtree:true,characterData:true})}catch(e){}}
/* English UI (default): leftover Arabic in the invigilation page follows the chosen language */
const EXX={'جاهز للطباعة والمشاركة':'Ready to print & share','منظم وقابل للتعديل':'Organised & editable','⏳ جارٍ التحضير…':'⏳ Preparing…','✔ تم التنزيل':'✔ Downloaded','⚠ تعذّر':'⚠ Failed','اليوم':'Day','القاعات':'Halls','المراقبون':'Invigilators','التصدير':'Export','أقرب يوم اختبار':'Nearest exam day','أيام اختبار قادمة':'Upcoming exam days','السبت':'Saturday','الأحد':'Sunday','الاثنين':'Monday','الإثنين':'Monday','الثلاثاء':'Tuesday','الأربعاء':'Wednesday','الخميس':'Thursday','الجمعة':'Friday'};
const EXS=[['اللغة الصينية','Chinese'],['اللغة الإنجليزية','English'],['اللغة العربية','Arabic'],['التربية الإسلامية','Islamic Studies'],['الدراسات الاجتماعية','Social Studies'],['الإحصاء','Statistics'],['الكيمياء','Chemistry'],['الأحياء','Biology'],['الفيزياء','Physics'],['الرياضيات','Mathematics'],['العلوم','Science'],['التربية البدنية','Physical Education'],['الحاسوب','Computer Science'],['الصفوف','Grades'],['قاعة','halls'],['طالب','students'],['xx_never','ready'],['سيُنشأ','will be created']];
function exEnTx(s){const k=s.trim();if(EXX[k])return s.replace(k,EXX[k]);let t=s.replace(/،/g,',').replace(/(\d)\s*جاهزة?(\s*·\s*ready)/g,'$1$2').replace(/(\d)\s*جاهزة?/g,'$1 ready');if(!/[A-Za-z]/.test(t))EXS.forEach(([a,b])=>{t=t.split(a).join(b)});return engClean(t,true)}
function exEnDom(root){if(window.__UL!=='en')return;try{const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:n=>ENG_AR.test(n.nodeValue)&&!(n.parentElement&&n.parentElement.closest('textarea,script,style,.etRoot,#etBig'))?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT});const L=[];let n;while((n=w.nextNode()))L.push(n);L.forEach(x=>{const v=exEnTx(x.nodeValue);if(v!==x.nodeValue)x.nodeValue=v})}catch(e){}}
