function rosterMatch(){const m=GM();if(!m)return null;const em=nrm(m.email),nm=nrm(m.name);return MS.roster.find(r=>{const rn=nrm(r.name),re=nrm(r.email);return(em&&re&&em===re)||(nm&&rn&&(nm===rn||(Math.min(nm.length,rn.length)>4&&(nm.includes(rn)||rn.includes(nm)))))})||null}
