(async function initMsg(){
 let db=null,user=null;
 try{if(window.claude&&claude.use){db=await claude.use('db');user=await claude.use('user')}}catch(e){}
 MS.db=db;
 if(user){try{MS.me=await user.me();MS.admin=!!(MS.me.canEdit||MS.me.isOwner)}catch(e){}}
 if(db){
  db.doc('coord/roster').onSnapshot(s=>{MS.roster=s.exists&&Array.isArray(s.data().list)?s.data().list:[];try{window.__gr=ROLE!=='student'&&!!(rosterMatch()||MS.roster.some(r=>{const em=String(r.email||'').toLowerCase();return em&&[String(TMAIL||'').toLowerCase(),String(window.__myEm||'').toLowerCase()].includes(em)||(window.__nameHit&&window.__nameHit(r.name))}))}catch(e){window.__gr=false}try{window.__applyGrant&&window.__applyGrant()}catch(e){}renderMsg();renderRoster()},()=>{});
  if(MS.me&&MS.me.id)db.doc('inbox/'+MS.me.id).onSnapshot(s=>{MS.mine=s.exists?s.data():null;renderMsg()},()=>{});
  if(MS.admin)db.collection('inbox').onSnapshot(sn=>{MS.inbox=sn.docs.map(d=>({uid:d.id,...d.data()}));renderMsg()},()=>{});
 }
 renderMsg();renderRoster();
})();




