 window.__occOn=iso=>{const q=String(iso).split('-').map(Number);if(q.length<3||q.some(isNaN))return[];return(occ(q[0],q[1]-1)[q[2]]||[]).map(x=>({n:x.ev?x.ev.t:x.n,ev:!!x.ev,d:(dscOf(x.n)||{}).d||''}))};
