  f.append(row('Category',[key('All',!ST.cat,()=>{ST.cat='';draw()}),...Object.keys(CAT).map(k=>key(CAT[k].ic+' '+CAT[k].t,ST.cat===k,()=>{ST.cat=ST.cat===k?'':k;draw()}))]));
  f.append(row('Entity',[key('All',!ST.ent,()=>{ST.ent='';draw()}),...['ATS','ADPOLY','FCHS','ADVETI'].map(k=>{const b=key(EN[k].n,ST.ent===k,()=>{ST.ent=ST.ent===k?'':k;draw()});b.title=EN[k].f;return b})]));
  f.append(row('Status',[['','All'],['now','● Now'],['week','Next 7 days'],['up','Upcoming'],['done','Ended']].map(([k,l])=>key(l,ST.stat===k,()=>{ST.stat=k;draw()}))));
  const sel=h('select','evsel');const o0=h('option','','All locations');o0.value='';sel.append(o0);places.forEach(p=>{const o=h('option','',p);o.value=p;sel.append(o)});sel.value=ST.place;sel.onchange=()=>{ST.place=sel.value;draw()};
  const di=h('input');di.type='date';di.className='evsel';di.min='2026-10-01';di.max='2026-12-31';di.value=ST.date;di.onchange=()=>{ST.date=di.value;draw()};
  const rs=h('button','btn','Reset ⟲');rs.onclick=()=>{Object.assign(ST,{q:'',cat:'',ent:'',stat:'',place:'',date:''});draw()};
  const r4=h('div','evrow');r4.append(h('span','evlb','Location'),sel,h('span','evlb','Date'),di,rs);f.append(r4);
  f.append(row('View',[['cat','🗂 By category'],['time','🕒 Timeline'],['cal','📅 Calendar']].map(([k,l])=>key(l,ST.view===k,()=>{ST.view=k;draw()}))));
  el.append(f);
  el.append(h('div','evcount','Showing '+list.length+' of '+all.length+' events'+(ST.date?' · active on '+DNm[dd(ST.date).getUTCDay()]+' '+dd(ST.date).getUTCDate()+' '+MN[dd(ST.date).getUTCMonth()]:'')));
