   const sec=h('section','evsec');const hd=h('div','evsh ec-'+k);hd.append(h('span','evsi',CAT[k].ic),h('b','',CAT[k].t),h('em','',ls.length+(ls.length>1?' events':' event')));sec.append(hd);
   if(k==='skills'){const p=h('div','evsk');p.append(h('div','evsk1','ACTVET × EmiratesSkills  ·  تحدي المهارات'),h('p','',SK_DESC));sec.append(p)}
   if(k==='intl')sec.append(h('div','evsk2','Engaging activities will be conducted to mark the occasion, raise awareness and encourage participation.'));
