 const fmtOf=(g,st)=>{const m=new Map();ALLX.filter(x=>x.g===g&&x.st===st).forEach(x=>x.parts.forEach(p=>{const k=p[2]+(p[4]||'')+(p[5]||'');if(!m.has(k)){const md=MODE[p[2]],sr=p[4]?SRC[p[4]]:null;m.set(k,[md[0],md[1]+(sr?' '+sr[0]:'')+(p[5]==='L'?' مع اختبار استماع':''),md[2]+(sr?' '+sr[1]:'')+(p[5]==='L'?' with listening':'')])}}));return [...m.values()]};
