 /* ---------- invigilation link ---------- */
 const EX=()=>{try{return window.__EXD&&window.__EXD.get&&window.__EXD.get()}catch(e){return null}};
 const canEd=()=>{try{return ROLE!=='student'&&!!(window.__EXD&&window.__EXD.can&&window.__EXD.can())}catch(e){return false}};
 function invOf(date){const S=EX();if(!S||!Array.isArray(S.days))return null;const ds=S.days.filter(d=>d.date===date);if(!ds.length)return{days:[],halls:0,inv:0};
  const halls=new Set(),names=new Set();ds.forEach(d=>{(S.venues||[]).forEach(v=>{const L=(d.inv&&d.inv[v.id])||[];if((d.sess||[]).some(s=>s.v===v.id)||L.length)halls.add(v.id);L.forEach(n=>names.add(n))})});
  return{days:ds,halls:halls.size,inv:names.size,pub:!!S.pubAt&&!S.draft}}
 const openInv=id=>{try{showView('exam');setTimeout(()=>{try{window.__exGo&&window.__exGo(id)}catch(e){}},60)}catch(e){}};
 function mkDay(date){const L=BD[date]||[];let a='99:99',b='00:00',allE=true;const sj=new Set();L.forEach(x=>{sj.add(SJ[x.sj][1]);x.parts.forEach(p=>{if(p[0]<a)a=p[0];if(p[1]>b)b=p[1];if(p[2]!=='E')allE=false})});
  return{date,title:'Final exams · '+[...sj].join(' / '),type:allE?'Electronic':'Paper',from:a,to:b,note:'Created from the Term 1 final exams timetable'}}
