 /* ---------- ICS ---------- */
 function ics(list,name){const z=n=>String(n).padStart(2,'0');const u=(date,t)=>{const [h,m]=t.split(':').map(Number);const x=new Date(Date.UTC(+date.slice(0,4),mo(date),dm(date),h-4,m));return x.getUTCFullYear()+z(x.getUTCMonth()+1)+z(x.getUTCDate())+'T'+z(x.getUTCHours())+z(x.getUTCMinutes())+'00Z'};
  const L=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//ATS Schedule Center//Final Exams//EN','CALSCALE:GREGORIAN','X-WR-CALNAME:Final Exams Term 1 2026-2027'];
  list.forEach((x,i)=>x.parts.forEach((p,j)=>{const s=SJ[x.sj];L.push('BEGIN:VEVENT','UID:fin-'+x.g+x.st+'-'+x.sj+'-'+j+'@ats-substitution','DTSTAMP:'+u(today(),'04:00'),'DTSTART:'+u(x.date,p[0]),'DTEND:'+u(x.date,p[1]),'SUMMARY:'+s[2]+' '+s[1]+' / '+s[0]+' — G'+x.g+' '+SN[x.st][1]+(x.c?' · '+x.c:''),'DESCRIPTION:'+MODE[p[2]][2]+(partLbl(x.parts,p)?' · '+partLbl(x.parts,p).split(' · ')[1]:'')+'. '+notesFor(x).filter(q=>!/Teachers/.test(q[2])).map(q=>q[2]).join(' '),'BEGIN:VALARM','TRIGGER:-P1D','ACTION:DISPLAY','DESCRIPTION:Exam tomorrow','END:VALARM','END:VEVENT')}));
  L.push('END:VCALENDAR');const blob=new Blob([L.join('\r\n')],{type:'text/calendar'});
  if(window.__dl)window.__dl(name,blob);else{const a=E('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();a.remove()}}
