/* ===== AI FIELD ASSIST (✨ suggestions for any field) ===== */
(function(){
let sample=null,off=false,cur=null,ctl=null,panel=null,fab=null,busy=false;
(async function(){try{if(window.claude&&claude.use)sample=await claude.use('sample')}catch(e){}if(typeof sample!=='function'){sample=null}})();
const EX='header.top,#sbar,#gate,.rail,#tb,#cp,.cpb,#v_teachers,#v_export,#meRoot,.subTools,.subModes,.exFil,.exTools,.exVm,.exDays,#ovbar,#aiP,#aiF,.smModes,.sbi';
const SEL='input:not([type=search]):not([type=file]):not([type=checkbox]):not([type=radio]):not([type=color]):not([type=range]):not([type=button]):not([type=submit]):not([type=hidden]),textarea,select';
const ok=el=>el&&el.matches&&el.matches(SEL)&&!el.disabled&&!el.readOnly&&!el.closest(EX)&&!el.hasAttribute('data-noai')&&el.offsetParent!==null;
const clean=t=>String(t||'').replace(/\s+/g,' ').trim();
function lbl(el){let t='';
 if(el.id){const l=document.querySelector('label[for="'+el.id+'"]');if(l)t=l.textContent}
 if(!t){const l=el.closest('label');if(l)t=[...l.childNodes].filter(n=>n.nodeType===3||(n.nodeType===1&&!n.matches('input,select,textarea,datalist')&&!n.querySelector('input,select,textarea'))).map(n=>n.textContent).join(' ')}
 if(!t){const td=el.closest('td');if(td){const tr=td.parentElement,i=[...tr.children].indexOf(td),tb=td.closest('table'),hr=tb&&tb.querySelector('thead tr,tr');if(hr&&hr.children[i])t=hr.children[i].textContent}}
 if(!t){const p=el.parentElement;const s=p&&p.querySelector(':scope>small,:scope>span.cl2,:scope>b');if(s&&!s.contains(el))t=s.textContent}
 return clean(t||el.placeholder||el.title||el.getAttribute('aria-label')||el.name||el.id).slice(0,90)}
function ctxFields(el){const box=el.closest('tr')||el.closest('.exV,.exZone,.ccard,.mc,article,.card,section')||el.parentElement;const o=[];
 if(!box)return o;box.querySelectorAll('input,select,textarea').forEach(x=>{if(x===el||o.length>=24||x.type==='search'||x.type==='file'||x.type==='checkbox'||x.type==='radio'||x.type==='password')return;let v=x.tagName==='SELECT'?(x.selectedOptions[0]?x.selectedOptions[0].text:''):x.value;v=clean(v);if(!v)return;o.push({field:lbl(x),value:v.slice(0,140)})});return o}
function viewName(el){const sm=el.closest('#sm');if(sm)return'Substitution picker dialog';const v=el.closest('.view');if(v){const b=v.querySelector('.vban h2');return clean(b?b.textContent:v.id)}return clean(document.title)}
function opts(el){if(el.tagName==='SELECT')return[...el.options].filter(o=>o.value!==''||o.text).slice(0,150).map(o=>({value:o.value,text:clean(o.text)}));
 const id=el.getAttribute('list');if(id){const dl=document.getElementById(id);if(dl)return[...dl.options].slice(0,120).map(o=>({value:o.value,text:clean(o.label||o.value)}))}return null}
function pos(){if(!cur||!fab)return;if(!document.body.contains(cur)||!ok(cur)){hide();return}const r=cur.getBoundingClientRect();
 if(r.bottom<0||r.top>innerHeight||r.width<30){fab.style.display='none';return}
 fab.style.display='flex';const w=26;fab.style.top=Math.max(2,Math.min(innerHeight-w-2,r.top+(r.height-w)/2))+'px';fab.style.left=Math.max(2,Math.min(innerWidth-w-4,r.right-w-(cur.tagName==='SELECT'?26:4)))+'px';
 if(panel&&panel.style.display!=='none')placePanel()}
function placePanel(){const r=cur.getBoundingClientRect(),pw=Math.min(380,innerWidth-16);panel.style.width=pw+'px';let l=Math.min(Math.max(8,r.left),innerWidth-pw-8),t=r.bottom+6;const ph=panel.offsetHeight||200;if(t+ph>innerHeight-8)t=Math.max(8,r.top-ph-6);panel.style.left=l+'px';panel.style.top=t+'px'}
function build(){if(fab)return;
 fab=document.createElement('button');fab.id='aiF';fab.type='button';fab.textContent='✨';fab.title='Suggest a value with AI';fab.style.display='none';
 fab.onmousedown=e=>e.preventDefault();fab.onclick=()=>openPanel();document.body.append(fab);
 panel=document.createElement('div');panel.id='aiP';panel.style.display='none';document.body.append(panel);
 addEventListener('scroll',pos,true);addEventListener('resize',pos)}
function hide(){if(fab)fab.style.display='none';closePanel();cur=null}
function closePanel(){if(ctl){try{ctl.abort()}catch(e){}ctl=null}if(panel)panel.style.display='none';busy=false}
document.addEventListener('focusin',e=>{if(off||!sample)return;const el=e.target;if(el.closest&&el.closest('#aiP'))return;if(ok(el)){build();cur=el;pos()}else if(!(el.id==='aiF')){if(fab){fab.style.display='none'}if(!el.closest||!el.closest('#aiP'))closePanel();cur=null}});
document.addEventListener('mousedown',e=>{if(panel&&panel.style.display!=='none'&&!e.target.closest('#aiP,#aiF')&&e.target!==cur)closePanel()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&panel&&panel.style.display!=='none'){closePanel();if(cur)cur.focus()}});
setInterval(()=>{if(cur&&fab&&fab.style.display!=='none')pos()},700);
const ERR={not_granted:'AI suggestions were not allowed for this page.',rate_limited:'Too many requests — please wait a moment and try again.',session_expired:'Please sign in again to use AI suggestions.',refused:'Claude could not suggest anything for this field.',invalid_json:'The answer could not be read — try again.',empty_completion:'No suggestion came back — try again or add a hint.',upstream_error:'A temporary problem occurred — try again.'};
function fmtOk(el,v){v=String(v==null?'':v).trim();const t=el.type;if(el.tagName==='SELECT'){const o=[...el.options];const m=o.find(x=>x.value===v)||o.find(x=>clean(x.text).toLowerCase()===v.toLowerCase());return m?m.value:null}
 if(t==='date')return /^\d{4}-\d\d-\d\d$/.test(v)?v:null;if(t==='time')return /^\d\d:\d\d$/.test(v)?v:null;if(t==='datetime-local')return /^\d{4}-\d\d-\d\dT\d\d:\d\d$/.test(v)?v:null;if(t==='number')return isFinite(+v)&&v!==''?v:null;if(t==='url')return /^https?:\/\//i.test(v)?v:null;return v||null}
async function run(hint,more){const el=cur;if(!el||!sample||busy)return;busy=true;const label=lbl(el);
 const body=panel.querySelector('.aiB');body.innerHTML='<div class="aiTh">✨ Thinking…</div>';
 const op=opts(el),today=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Dubai'}),dow=new Date().toLocaleDateString('en-GB',{timeZone:'Asia/Dubai',weekday:'long'});
 const prompt=`You help a school coordinator fill ONE form field in a school management web app (Applied Technology High School, Ras Al Khaimah, UAE; school week Monday–Friday; dates and times are Asia/Dubai; today is ${dow} ${today}).
Page: ${viewName(el)}
Field: "${label}" (input type: ${el.tagName==='SELECT'?'dropdown':el.tagName==='TEXTAREA'?'long text':(el.type||'text')})
${op?'Allowed options (use one VERBATIM as the value): '+JSON.stringify(op.map(o=>o.value===o.text||!o.value?o.text:o.value+' = '+o.text))+'\n':''}Current value: ${JSON.stringify(el.tagName==='SELECT'?(el.selectedOptions[0]?el.selectedOptions[0].text:''):el.value)}
Other filled fields in the same row/card: ${JSON.stringify(ctxFields(el))}
${hint?"Coordinator's hint: "+hint+'\n':''}${more?'Give different suggestions from the common ones.\n':''}Reply with ONLY JSON: {"suggestions":[{"value":"...","why":"short reason, max 12 words"}]} — 1 to 3 different, realistic suggestions. "value" is exactly what goes into the field. Formats: date YYYY-MM-DD; time HH:MM (24h); datetime-local YYYY-MM-DDTHH:MM; number digits only; dropdown/list fields: an allowed option verbatim. Keep text concise and professional, in the language of the hint or of the existing page text (English by default). Never invent phone numbers, emails or personal data. If nothing sensible can be suggested reply {"suggestions":[]}.`;
 ctl=new AbortController();
 try{const r=await sample.json(prompt,{modelTier:el.tagName==='TEXTAREA'?'default':'quick',signal:ctl.signal,cache:more?false:true});
  if(cur!==el){busy=false;return}
  const arr=(r&&Array.isArray(r.suggestions)?r.suggestions:Array.isArray(r)?r:[]).map(s=>({value:s&&s.value!=null?s.value:s,why:s&&s.why||''})).map(s=>({v:fmtOk(el,s.value),why:s.why,raw:s.value})).filter(s=>s.v!=null).slice(0,3);
  body.innerHTML='';if(!arr.length){body.innerHTML='<div class="aiTh">No suggestion for this field — try adding a hint.</div>'}
  arr.forEach(s=>{const row=document.createElement('div');row.className='aiS';const tx=document.createElement('div');tx.className='aiV';let shown=s.v;if(el.tagName==='SELECT'){const o=[...el.options].find(x=>x.value===s.v);shown=o?clean(o.text):s.v}tx.textContent=shown;
   const w=document.createElement('small');w.textContent=s.why;const b=document.createElement('button');b.type='button';b.textContent='Use';b.onclick=()=>{apply(el,s.v);closePanel()};row.append(tx,w,b);body.append(row)});
 }catch(e){if(e&&e.code==='cancelled'){busy=false;return}const c=e&&e.code;body.innerHTML='';const m=document.createElement('div');m.className='aiTh';m.textContent=ERR[c]||'Could not get a suggestion.';body.append(m);if(c==='not_granted'||c==='sampling_disabled'||c==='not_declared'||c==='capability_disabled'||c==='capability_removed'){off=true;if(fab)fab.style.display='none'}}
 busy=false;ctl=null;placePanel()}
function apply(el,v){el.focus();if(el.tagName==='SELECT')el.value=v;else{const d=Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el),'value');if(d&&d.set)d.set.call(el,v);else el.value=v}
 el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}))}
function openPanel(){if(!cur||!sample)return;panel.innerHTML='';panel.style.display='block';
 const hd=document.createElement('div');hd.className='aiH';const t=document.createElement('b');t.textContent='✨ AI suggestion — '+lbl(cur);const x=document.createElement('button');x.type='button';x.textContent='✕';x.onclick=()=>{closePanel();if(cur)cur.focus()};hd.append(t,x);
 const hr=document.createElement('div');hr.className='aiR';const hi=document.createElement('input');hi.type='text';hi.placeholder='Optional hint (any language)…';hi.setAttribute('data-noai','1');
 const go=document.createElement('button');go.type='button';go.textContent='Suggest';go.onclick=()=>{ctl&&ctl.abort();busy=false;run(hi.value.trim(),false)};
 const more=document.createElement('button');more.type='button';more.textContent='↻ Another';more.onclick=()=>{ctl&&ctl.abort();busy=false;run(hi.value.trim(),true)};
 hi.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();go.click()}};hr.append(hi,go,more);
 const body=document.createElement('div');body.className='aiB';const nt=document.createElement('div');nt.className='aiN';nt.textContent='Suggestions only — review before using. Uses your own Claude account.';
 panel.append(hd,hr,body,nt);placePanel();run('',false)}
})();

