/* ===== AUTO RAMADAN TIMING ===== */
(function(){const HM=new Intl.DateTimeFormat('en-u-ca-islamic-umalqura',{month:'numeric',timeZone:'UTC'});let last=null;
 const isRam=()=>{try{const c=window.__cfgRam?window.__cfgRam():null;if(c!==null&&c!==undefined)return c;const f=todayDubai().split('-').map(Number);return parseInt(HM.formatToParts(new Date(Date.UTC(f[0],f[1]-1,f[2],12))).find(x=>x.type==='month').value,10)===9}catch(e){return false}};
 function chk(first){const r=isRam();if(r===last)return;const was=last;last=r;if(RM!==r){setMode(r?1:0)}
  if(was!==null||r){try{if(r)bellToast('🌙 Ramadan Kareem — Ramadan timing is now active automatically','start');else if(was!==null)bellToast('Ramadan has ended — regular timing is active again','end')}catch(e){}}}
 window.__autoRam=chk;chk(true);setInterval(chk,60000)})();

/* ===== LIVE: people online + reactions ===== */
(function(){
 const EM=['👍','❤️','😊','👏','🎉'],top=document.getElementById('top');if(!top)return;
 const box=document.createElement('div');box.id='liveBox';box.innerHTML='<span class="lvN" id="lvN" title="Signed-in viewers only: people opening the public link without a Claude sign-in cannot be counted · يُحسب فقط من سجّل دخوله إلى Claude"><i></i><b>1</b><span class="lvW"> online</span></span><span class="lvR" role="group" aria-label="Reactions"></span>';top.append(box);
 const cnt={},seen={},R=box.querySelector('.lvR');let room=null,last=0;
 EM.forEach(e=>{cnt[e]=0;const b=document.createElement('button');b.type='button';b.dataset.e=e;b.title='Send '+e;b.innerHTML=e+'<small data-n="0"></small>';b.onclick=()=>{const n=Date.now();if(n-last<350)return;last=n;fly(b,e);bump(e);try{room&&room.presence({r:{k:e,t:n}})}catch(x){}};R.append(b)});
 function bump(e){cnt[e]++;const sm=R.querySelector('[data-e="'+e+'"] small');if(sm){sm.textContent=cnt[e];sm.dataset.n=cnt[e]}}
 function fly(from,e){const r=from.getBoundingClientRect(),f=document.createElement('span');f.className='lvFly';f.textContent=e;f.style.left=(r.left+r.width/2-14+(Math.random()*30-15))+'px';f.style.top=(r.bottom+4)+'px';document.body.append(f);setTimeout(()=>f.remove(),2300)}
 function setN(n){const b=box.querySelector('#lvN b');if(b)b.textContent=n;box.querySelector('#lvN').lastChild.textContent=' online'}
 (async function(){try{if(window.claude&&claude.use)room=await claude.use('room')}catch(e){}
  if(!room){try{const db=await claude.use('db'),U=await claude.use('user'),id=db&&U&&U.id?await U.id():null;if(!db||!id)return;
   const nm=()=>(window.__getMyName&&window.__getMyName())||'';let last=[];
   const beat=()=>{if(document.hidden)return;db.doc('presence/'+id).set({t:Date.now(),n:nm()}).catch(()=>{})};beat();setInterval(beat,30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)beat()});
   const show=()=>{const now=Date.now(),L=last.filter(x=>now-(+x.t||0)<120000);window.__online=L.map(x=>x.n||'');setN(Math.max(1,L.length));const lv=box.querySelector('#lvN');if(lv)lv.title='المتواجدون الآن · Online now ('+L.length+'): '+L.map(x=>x.n).filter(Boolean).join('، ')};
   db.collection('presence').onSnapshot(q=>{last=(q.docs||[]).map(d=>d.data()||{});show()},()=>{});setInterval(show,20000)}catch(e){}return}
  const t0=Date.now();
  room.onPeers(peers=>{const ids=new Set();peers.forEach(p=>{if(p.kind==='agent')return;ids.add(p.by||p.peer)});setN(Math.max(1,ids.size));
   peers.forEach(p=>{if(p.isMe||p.kind==='agent')return;const r=p.presence&&p.presence.r;if(!r||typeof r.k!=='string'||!EM.includes(r.k))return;const t=+r.t||0;
    if(seen[p.peer]===undefined){seen[p.peer]=t;if(Date.now()-t>8000)return}else if(seen[p.peer]===t)return;seen[p.peer]=t;
    const b=R.querySelector('[data-e="'+r.k+'"]');if(b){fly(b,r.k);bump(r.k)}})},()=>{})})();
})();

