const AR=()=>window.__UL!=='en';
const DAR=['الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت','الأحد'],DEN=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
const SAR={'MATHS':'الرياضيات','PHYSICS':'الفيزياء','BIOLOGY':'الأحياء','CHEMISTRY':'الكيمياء','ENGLISH':'اللغة الإنجليزية','ARABIC':'اللغة العربية','ISLAMIC':'التربية الإسلامية','SOCIAL STUDIES':'الدراسات الاجتماعية','STATISTICS':'الإحصاء'};
const subAr=s=>SAR[s]||s.replace(/^CS · /,'علوم الحاسوب ').replace(/^AI · /,'الذكاء الاصطناعي ');
const parse=s=>{const [y,m,d]=s.split('-').map(Number);return Date.UTC(y,m-1,d)};
const wd=s=>(new Date(parse(s)).getUTCDay()+6)%7;
const addD=(s,n)=>new Date(parse(s)+n*864e5).toISOString().slice(0,10);
const fd=(s,ar)=>{const [y,m,d]=s.split('-').map(Number),w=wd(s);return ar?DAR[w]+' '+d+' نوفمبر '+y:DEN[w]+' '+d+' Nov '+y};
const tz=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Dubai'});
const ft=t=>t?t.replace(/(AM|PM)$/,' $1'):'';
const ftA=t=>t?t.replace(/AM$/,' ص').replace(/PM$/,' م'):'';
const byC={};QZ.R.forEach(r=>(byC[r.c]=byC[r.c]||[]).push(r));
const live=()=>tz()<=QZ.until;
function evFor(l){const out={q:[],s:[]};
 for(const r of byC[l.c]||[]){if(!r.k.includes(l.k))continue;
  const LS=ALL.filter(x=>x.c===r.c&&r.k.includes(x.k));
  const first=d=>LS.filter(x=>d==null||x.d===d).sort((a,b)=>a.d-b.d||a.p-b.p)[0];
  const same=x=>x&&x.d===l.d&&x.p===l.p&&x.c===l.c&&x.k===l.k;
  if(r.q&&r.q.d){const di=wd(r.q.d);let t=null,mis=false;
   if(r.q.p)t=LS.find(x=>x.d===di&&x.p<=r.q.p&&r.q.p<x.p+x.s);else t=first(di);
   if(!t){t=first(di)||first(null);mis=true}
   if(same(t))out.q.push({r,q:r.q,mis})}
  r.s.forEach(s=>{if(!s.d)return;const di=wd(s.d),inWk=s.d>=QZ.wk&&s.d<=addD(QZ.wk,4)&&di<5;
   const t=inWk?(first(di)||first(null)):first(null);if(same(t))out.s.push({r,s})})}
 return out}
