 const inSD=n=>{try{const e=n.nodeType===3?n.parentElement:n;return !!(e&&e.closest&&e.closest('#v_sub,.smc,#dyM,#subSend,#slM,#saOv,#arM'))}catch(x){return false}};
 const LEADR=/^[^\p{L}\p{N}(]*/u;
 function sdCore(core){ /* returns translated core or null */
  if(UL==='ar'){if(SDEN.has(core))return SDEN.get(core);const m=/^(.+?) \((\d+)\)$/.exec(core);if(m&&SDEN.has(m[1]))return SDEN.get(m[1])+' ('+m[2]+')';
   let r=/^Period (\d+)$/.exec(core);if(r)return 'الحصة '+r[1];r=/^Today · (\S+) \((\d+)\)$/.exec(core);if(r)return 'اليوم · '+r[1]+' ('+r[2]+')';r=/^Upcoming \((\d+)\)$/.exec(core);if(r)return 'القادمة ('+r[1]+')';return null}
  if(SDAR.has(core))return SDAR.get(core);const m=/^(.+?) \((\d+)\)$/.exec(core);if(m&&SDAR.has(m[1]))return SDAR.get(m[1])+' ('+m[2]+')';
  let r=/^الحصة (\d+)$/.exec(core);if(r)return 'Period '+r[1];r=/^اليوم · (\S+) \((\d+)\)$/.exec(core);if(r)return 'Today · '+r[1]+' ('+r[2]+')';return null}
 const SDRX=[[/⛔ Time conflict — (.+?) has a lesson at the same time: period (.+?) · (.+?) · (.+?)\. Lessons must not overlap\./g,'⛔ تعارض في الوقت — $1 لديه حصة في الوقت نفسه: الحصة $2 · $3 · $4. يجب ألا تتداخل الدروس.'],[/⛔ Time conflict — (.+?) is assigned as substitute at the same time \(period (.+?) · (.+?) · for the absent teacher (.+?)\)\./g,'⛔ تعارض في الوقت — $1 معيَّن بديلًا في الوقت نفسه (الحصة $2 · $3 · عن المعلم الغائب $4).'],[/⚠ Available at this time, but he will then have (\d+) lessons today \(more than 5\)\./g,'⚠ متاح في هذا الوقت، لكن سيكون لديه $1 دروس اليوم (أكثر من 5).'],[/✔ Available in period (\d+) (\([^)]*\)) — he will then have (\d+) lessons today\./g,'✔ متاح في الحصة $1 $2 — وسيكون لديه $3 دروس اليوم.'],[/✔ Additional staff \(no timetable\) — free in period (\d+) (\([^)]*\))\./g,'✔ موظف إضافي (بلا جدول) — متفرغ في الحصة $1 $2.'],[/has (\d+) lessons this day/g,'لديه $1 درسًا في هذا اليوم'],[/has (\d+) lessons · after assignment (\d+)/g,'لديه $1 درسًا · بعد التعيين $2'],[/⚠ Over 5 lessons/g,'⚠ أكثر من 5 دروس'],[/\+ (\d+) More suggestions in the full list\./g,'+ $1 اقتراحات أخرى في القائمة الكاملة.'],[/\nFree$/,'\nمتفرغ'],[/· (\d+) days? · (\d+) periods?/g,'· $1 يوم · $2 حصة'],[/\bP(\d+)\b/g,'ح$1'],[/\b(Mon|Tue|Wed|Thu|Fri|Sat|Sun)\b(?=\s|$)/g,(m)=>({Mon:'الاثنين',Tue:'الثلاثاء',Wed:'الأربعاء',Thu:'الخميس',Fri:'الجمعة',Sat:'السبت',Sun:'الأحد'})[m]]];
 function sd(s,n){
  if(!s||!n||!inSD(n))return s;const t=s.trim();if(!t)return s;
  if(UL==='ar'&&!LT.test(t))return s;if(UL==='en'&&!AR.test(t))return s;
  const lead=LEADR.exec(s)[0],rest=s.slice(lead.length);
  const c=sdCore(rest.trimEnd());if(c!==null)return lead+c+(rest.length-rest.trimEnd().length?' ':'');
  {const tr=/[^\p{L}\p{N})]*$/u.exec(rest)[0],core=rest.slice(0,rest.length-tr.length);if(core&&tr){const c2=sdCore(core);if(c2!==null)return lead+c2+tr}}
  let o=s;
  if(UL==='ar'){for(const [rg,rp] of SDRX)o=o.replace(rg,rp);for(const [e,a] of SDPAR)if(o.includes(e))o=o.split(e).join(a);
   o=o.replace(/\b(Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday)\b/g,m=>SDEN.get(m));o=o.replace(/(^|[ ·—(])(Physical Education|Computer Science|Mathematics|Islamic Studies|Social Studies|Physics|Chemistry|Biology|Arabic|English)(?= · |$| \()/g,(m,p,w)=>p+SDEN.get(w));
   o=o.replace(/\bPeriod (\d+)/g,'الحصة $1').replace(/(\d+)\/(\d+) covered/g,'$1/$2 تمت التغطية').replace(/(\d+) records?/g,'$1 سجل').replace(/(\d+) lessons?/g,'$1 درس').replace(/(\d+) weekly/g,'$1 أسبوعيًا')}
  else{for(const [a,e] of SDREV)if(o.includes(a))o=o.split(a).join(e);
   o=o.replace(/(الاثنين|الثلاثاء|الأربعاء|الخميس|الجمعة|السبت|الأحد)/g,m=>SDAR.get(m))}
  return o}
 function conv(s){
  if(UL==='ar'&&s&&LT.test(s))for(const [x,y] of DIC)if(s.includes(x))s=s.split(x).join(y);
  if(!s||!AR.test(s)||!LT.test(s))return s;
  const parts=s.split(SEP);if(parts.length<3)return s;
  const seg=parts.filter((p,i)=>i%2===0);
  if(!seg.some(isA)||!seg.some(isL))return s;
  const drop=UL==='ar'?isL:isA;
  const keep=seg.filter(p=>!drop(p));
  return keep.length?keep.join(' · '):s;
 }
