  const b=window.__ulBtn;if(b){b.innerHTML='<span class="'+(UL==='ar'?'on':'')+'">ع</span><span class="'+(UL==='en'?'on':'')+'">EN</span>';b.title=UL==='ar'?'Switch to English':'التبديل إلى العربية'}
  try{const hq=document.getElementById('hq');if(hq)delete hq.dataset.ar}catch(e){}
  ['myDock','ntBtn','sbxBtn','absBtn'].forEach(i=>{const o=document.getElementById(i);if(o)o.remove()});
  try{const rc=document.getElementById('rolechip');if(rc){const en=UL==='en',st=rc.firstChild;if(st&&st.nodeType===3)st.data=(window.ROLE_STU||document.body.dataset.role==='student')?(en?'🎓 Student':'🎓 طالب'):(en?'👩‍🏫 Teacher':'👩‍🏫 معلم');const bt=rc.querySelector('button');if(bt)bt.textContent=en?'Exit':'خروج'}}catch(e){}
  try{window.dispatchEvent(new CustomEvent('ulchange',{detail:UL}))}catch(e){}
  setTimeout(()=>{try{const id=(window.__curView&&window.__curView())||null;if(id&&typeof showView==='function')showView(id)}catch(e){}walk(document.body);PAIRS()},60);
