/* hover zoom: keep the enlarged lesson inside its scroll box */
document.addEventListener('mouseover',e=>{const k=e.target.closest&&e.target.closest('.board .key');if(!k||k._zo)return;k._zo=1;const c=k.closest('.scroll');if(!c)return;
 const r=k.getBoundingClientRect(),C=c.getBoundingClientRect(),cl=(v,a,b)=>Math.min(Math.max(v,a),b);
 const lx=1-(C.right-r.right)/r.width,hx=(r.left-C.left)/r.width,ly=1-(C.bottom-r.bottom)/r.height,hy=(r.top-C.top)/r.height;
 const fx=cl(.5,Math.min(lx,hx),Math.max(lx,hx)),fy=cl(.5,Math.min(ly,hy),Math.max(ly,hy));
 k.style.transformOrigin=(cl(fx,0,1)*100)+'% '+(cl(fy,0,1)*100)+'%'},true);
addEventListener('mouseout',e=>{const k=e.target.closest&&e.target.closest('.board .key');if(k)k._zo=0},true);

