  box.innerHTML='<h4>📝 Exam tomorrow — '+escH(dt)+'</h4><small>Reminder and instructions · تذكير بالاختبار غدًا</small>'+my.map(r=>'<div class="r"><b>'+escH(r.cls)+'</b> · '+escH(r.subj||r.code||'Exam')+' · '+escH(r.from)+'–'+escH(r.to)+(r.hall?' · '+escH(r.hall):'')+' · '+(r.ty==='Electronic'?'💻 Electronic':'📄 Paper')+(r.reqs.length?'<div class="q">'+r.reqs.map(x=>'<span>'+escH(x)+'</span>').join('')+'</div>':'')+'</div>').join('')+'<button class="btn go" id="exRemGo">Open exam schedule</button> <button class="btn" id="exRemX">Got it</button>';
