  const dt=document.createElement('details');dt.className='tbSnd';const sm=document.createElement('summary');sm.textContent='⚙ More: sounds & message';dt.append(sm);sl.forEach(l=>dt.append(l));{const bn=$$('bn');if(bn)dt.append(bn)}
  tb.prepend(hd);t1.after(rb);const pg=tb.querySelector('.pg');(pg||rb).after(dt);
