/* Interface color also drives the table background and frame (optional) */
(function(){
 const $=id=>document.getElementById(id),cm=$('cmatch');if(!cm)return;
 cm.checked=save.match!==false;
 const hexOf=c=>{c=String(c||'').trim();if(/^#[0-9a-f]{6}$/i.test(c))return c;if(/^#[0-9a-f]{3}$/i.test(c))return '#'+c.slice(1).split('').map(x=>x+x).join('');const m=/rgba?\((\d+)[ ,]+(\d+)[ ,]+(\d+)/.exec(c);return m?'#'+[m[1],m[2],m[3]].map(v=>(+v).toString(16).padStart(2,'0')).join(''):null};
 const cv=n=>{const e=document.createElement('i');e.style.color='var('+n+')';document.body.append(e);const v=getComputedStyle(e).color;e.remove();return hexOf(v)};
 function sync(){if(!cm.checked)return;const k2=cv('--k2'),ke=cv('--ke');if(!k2||!ke)return;save.bg={c:k2};save.fr={c:ke};try{persist()}catch(e){}try{applyBoard()}catch(e){}$('bgc').value=k2;$('frc').value=ke}
 cm.onchange=()=>{save.match=cm.checked;try{persist()}catch(e){}if(cm.checked)sync()};
 const later=()=>setTimeout(sync,30);
 $('th').addEventListener('click',later);$('cr').addEventListener('click',later);$('cu').addEventListener('input',later);
 /* picking a table color by hand switches the match off */
 const off=()=>{cm.checked=false;save.match=false;try{persist()}catch(e){}};
 $('bgs').addEventListener('click',off);$('frs').addEventListener('click',off);$('bgc').addEventListener('input',off);$('frc').addEventListener('input',off);
})();

