/* ===== electronic timer: fit everything on one full screen ===== */
(function(){
 let last='';
 function fit(){const r=document.getElementById('etBig');if(!r||!r.classList.contains('etFull')){return}
  let w=r.querySelector(':scope>.etFit');if(!w){w=document.createElement('div');w.className='etFit'}
  [...r.childNodes].forEach(n=>{if(n!==w)w.appendChild(n)});if(w.parentNode!==r)r.appendChild(w);
  const cs=getComputedStyle(r),av=r.clientHeight-parseFloat(cs.paddingTop)-parseFloat(cs.paddingBottom),aw=r.clientWidth-parseFloat(cs.paddingLeft)-parseFloat(cs.paddingRight);
  const test=z=>{w.style.zoom=z;w.style.width=(aw/z)+'px';return w.getBoundingClientRect().height<=av+1&&w.scrollWidth*z<=aw+2};
  let lo=0.15,hi=1,z;if(test(1))z=1;else{for(let k=0;k<8;k++){const m=(lo+hi)/2;if(test(m))lo=m;else hi=m}z=lo}
  w.style.zoom=z;w.style.width=(aw/z)+'px';const sig=z.toFixed(3)+'|'+aw+'|'+av;last=sig}
 setInterval(fit,500);addEventListener('resize',fit);document.addEventListener('fullscreenchange',()=>setTimeout(fit,80));
})();

