 const SUBINFO={};DEPT.forEach(d=>d.subs.forEach(s=>SUBINFO[s[0]]={code:s[0],en:s[1],ar:s[2]||s[1],ic:s[3],dept:d}));
 const GRADES=[9,10,11,12],GN={9:'التاسع',10:'العاشر',11:'الحادي عشر',12:'الثاني عشر'};
