 /* ---- term calendar ---- */
 const SETK='tt_pl_set';
 let SET={start:'2026-08-31',skip:['2026-10-12']};
 try{const o=JSON.parse(localStorage.getItem(SETK)||'null');if(o&&o.start)SET=o}catch(e){}
 const iso=d=>d.toISOString().slice(0,10);
 const addD=(s,n)=>{const d=new Date(s+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return iso(d)};
 const monOf=s=>{const d=new Date(s+'T12:00:00Z');return addD(s,-((d.getUTCDay()+6)%7))};
 function weekStart(n){let cur=monOf(SET.start),k=0;const sk=(SET.skip||[]).map(monOf);for(let i=0;i<400;i++){if(!sk.includes(cur)){k++;if(k===n)return cur}cur=addD(cur,7)}return ''}
 function weekOf(date){const m=monOf(date),sk=(SET.skip||[]).map(monOf);if(m<monOf(SET.start))return{n:0,brk:false};let cur=monOf(SET.start),k=0;for(let i=0;i<400;i++){const b=sk.includes(cur);if(!b)k++;if(cur===m)return{n:b?0:k,brk:b,last:k};cur=addD(cur,7)}return{n:0,brk:false}}
 const todayD=()=>{try{return todayDubai()}catch(e){return iso(new Date())}};
 const fmt=(a,b)=>{const f=s=>new Date(s+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'UTC'});return f(a)+' – '+f(addD(b||a,0))};
 const rangeOf=n=>{const s=weekStart(n);return s?fmt(s,addD(s,4)):''};
 /* ---- done marks ---- */
 const me=()=>{try{return String(window.__myEm||TMAIL||'guest').toLowerCase()}catch(e){return'guest'}};
 const DK=()=>'tt_pl_done_'+me()+(SET.term?'_'+SET.term:'');
