 const wnum=(w,i)=>/مراجعات|مراجعة/.test(w.title)?0:i+1;
 const wtitle=(w,i)=>{const n=wnum(w,i);return n?('Week '+n+' · '+clean(w.title)):clean(w.title)};
 function progress(sub,g,t){const ws=weeksOf(sub,g,t);if(!ws)return{d:0,n:0};let n=0,d=0;ws.forEach((w,wi)=>w.lessons.forEach(l=>{if(!l.name)return;n++;if(DONE[key(sub,g,t,wi,l)])d++}));return{d,n}}
