/* ===== substitution set-up screen: secondary controls tucked into a drop-down ===== */
(function(){try{if(window.__subLay)return;window.__subLay=1;let t=null;
 function lay(){try{const v=document.getElementById('v_sub');if(!v)return;const box=v.querySelector('#subCtl'),tools=v.querySelector('.tools');if(!box||!tools)return;
  let mo=box.querySelector('#subMore');
  if(!mo){mo=document.createElement('details');mo.id='subMore';mo.className='subMore';const sm=document.createElement('summary');sm.textContent='⚙ خيارات إضافية: قسمي، الحالة، المعلمون الغائبون · More options';mo.append(sm);const body=document.createElement('div');body.className='smBody';mo.append(body);
   try{mo.open=localStorage.getItem('tt_smOpen')==='1'}catch(e){}mo.addEventListener('toggle',()=>{try{localStorage.setItem('tt_smOpen',mo.open?'1':'0')}catch(e){}});box.append(mo)}
  const body=mo.querySelector('.smBody');
  ['#stTabs','#depAb'].forEach(s=>{const e=box.querySelector(s);if(e&&e.parentNode!==body)body.append(e)});
  const md=v.querySelector('.mydept');if(md&&md.parentNode!==body)body.prepend(md);
  const all=[...v.querySelectorAll('.subAdd')];const ad=all.find(x=>x.parentNode!==tools)||all[0];all.forEach(x=>{if(x!==ad)x.remove()});v.classList.toggle('subHasAdd',!!ad);
  if(ad&&ad.parentNode!==tools){ad.classList.add('subAddT');const sv=tools.querySelector('#s_sub');tools.insertBefore(ad,sv||null)}
 }catch(e){}}
 const run=()=>{clearTimeout(t);t=setTimeout(lay,60)};
 const v=document.getElementById('v_sub');if(v){new MutationObserver(run).observe(v,{childList:true,subtree:true})}run();
 try{const _dl=drawSub;drawSub=function(E){_dl(E);try{clearTimeout(t);lay()}catch(e){}}}catch(e){}
}catch(e){}})();

/* ===== modern calm design for the Substitution page ===== */
(function(){try{if(document.getElementById('subModern'))return;const st=document.createElement('style');st.id='subModern';st.textContent="/* ===== Modern calm design for the Substitution page (Apple / Microsoft Fluent inspired) ===== */\n#v_sub{--mA:#0a6cff;--mA2:#0058d6;--mInk:#1d1d1f;--mMut:#6e6e73;--mLine:#e5e5ea;--mBg:#f5f5f7;--mCard:#fff;\n background:linear-gradient(180deg,#f7f8fb 0%,#eef1f7 100%)!important;color:var(--mInk)!important;font-family:-apple-system,BlinkMacSystemFont,\"SF Pro Text\",\"Segoe UI Variable\",\"Segoe UI\",Inter,Cairo,system-ui,sans-serif!important;-webkit-font-smoothing:antialiased}\n#v_sub *{letter-spacing:0}\n#v_sub .ph .mode,#v_sub .mode,#v_sub .dlBar b,#v_sub .msBar b,#v_sub .mydept label,#v_sub #subCtl>div b,#v_sub #subCtl>div small,#v_sub #subCtl>div span:not(.chip){color:var(--mMut)!important;text-shadow:none!important;font-weight:600!important}\n/* banner + brand bar */\n#v_sub .vban,#v_sub div.vban.hasCq{background:var(--mCard)!important;border:1px solid var(--mLine)!important;border-radius:20px!important;box-shadow:0 1px 2px rgba(0,0,0,.04),0 8px 24px -12px rgba(20,30,60,.12)!important;backdrop-filter:none!important}\n#v_sub .vban h2,#v_sub .vban p,#v_sub div.vban.hasCq h2,#v_sub div.vban.hasCq p{color:var(--mInk)!important;text-shadow:none!important}\n#v_sub .vban p{color:var(--mMut)!important}\n#v_sub .vban .vi{width:56px!important;height:56px!important;font-size:28px!important;background:linear-gradient(145deg,#eaf2ff,#d6e6ff)!important;border:0!important;box-shadow:none!important;border-radius:16px!important}\n#subOrbit .so-hd{background:var(--mCard)!important;border:1px solid var(--mLine);border-radius:18px!important;box-shadow:0 1px 2px rgba(0,0,0,.04),0 8px 24px -14px rgba(20,30,60,.14)!important}\n#subOrbit .so-tx b{color:var(--mInk)!important;font-weight:700}#subOrbit .so-tx span{color:var(--mA)!important}\n#subOrbit .so-tg{background:var(--mA)!important;color:#fff!important;border:0!important;border-radius:12px!important;padding:11px 20px!important;font:600 15px -apple-system,\"Segoe UI\",Cairo,system-ui,sans-serif!important;box-shadow:0 1px 2px rgba(0,60,160,.3)!important}\n#subOrbit .so-tg:hover{background:var(--mA2)!important}\n#subOrbit .so-pn{background:var(--mCard)!important;border:1px solid var(--mLine)!important;border-radius:18px!important;box-shadow:0 12px 32px -16px rgba(20,30,60,.2)}\n#subOrbit .so-b{background:#f5f5f7!important;border:1px solid transparent!important;border-radius:14px!important;box-shadow:none!important;color:var(--mInk)!important}\n#subOrbit .so-b:hover{background:#eaf2ff!important;border-color:#cfe0ff!important;transform:none!important;box-shadow:none!important}\n#subOrbit .so-b b{color:var(--mInk)!important;font-weight:600!important}#subOrbit .so-b small{color:var(--mMut)!important;font-weight:500!important}\n#subOrbit .so-b.go{background:var(--mA)!important;border-color:var(--mA)!important}#subOrbit .so-b.go b,#subOrbit .so-b.go small{color:#fff!important}\n/* cards / groups */\n#v_sub .card{background:transparent!important}\n#v_sub .card .mydept,#v_sub .card .tools,#v_sub .mydept,#v_sub .tools,#v_sub #subCtl>div,#v_sub #depTabs{background:var(--mCard)!important;border:1px solid var(--mLine)!important;border-radius:18px!important;box-shadow:0 1px 2px rgba(0,0,0,.03),0 6px 18px -12px rgba(20,30,60,.12)!important;backdrop-filter:none!important;color:var(--mInk)!important}\n#v_sub .mydept,#v_sub .mydept *{color:var(--mInk)}\n#v_sub .mydept label{color:var(--mMut)!important}\n/* chips = Apple style segmented pills, buttons = flat */\n#v_sub .chip,#v_sub .btn{background:#f2f2f7!important;color:var(--mInk)!important;border:1px solid transparent!important;border-radius:999px!important;font-weight:600!important;font-size:14.5px!important;padding:8px 16px!important;box-shadow:none!important;transition:background .15s,transform .1s,box-shadow .15s}\n#v_sub .chip:hover,#v_sub .btn:hover{background:#e8e8ef!important;transform:none!important;box-shadow:none!important}\n#v_sub .chip:active,#v_sub .btn:active{transform:scale(.98)!important}\n#v_sub .chip.on,#v_sub #s_sub,#v_sub #a_sub{background:var(--mA)!important;color:#fff!important;border-color:var(--mA)!important;box-shadow:0 1px 2px rgba(0,60,160,.25)!important}\n#v_sub .chip.on:hover,#v_sub #s_sub:hover,#v_sub #a_sub:hover{background:var(--mA2)!important}\n#v_sub .btn.sndTb,#v_sub .sndTb{background:#eaf2ff!important;color:var(--mA)!important;border-color:#d3e3ff!important}\n#v_sub .subMini{font-size:13.5px!important;padding:6px 13px!important}\n#v_sub .dlB{background:#eaf2ff!important;color:var(--mA)!important;border:1px solid #d3e3ff!important;font-weight:600!important}\n#v_sub .dlB:hover{background:#dbe9ff!important}\n#v_sub .msDel{background:#fff0ef!important;color:#d70015!important;border:1px solid #ffd7d4!important}\n#v_sub .chip:focus-visible,#v_sub .btn:focus-visible,#v_sub input:focus-visible,#v_sub select:focus-visible{outline:3px solid rgba(10,108,255,.35)!important;outline-offset:1px}\n/* inputs */\n#v_sub input[type=search],#v_sub input[type=date],#v_sub input[type=text],#v_sub select{background:#fff!important;color:var(--mInk)!important;border:1px solid #d2d2d7!important;border-radius:12px!important;box-shadow:none!important;font-size:15px!important;padding:10px 14px!important}\n#v_sub input[type=search]::placeholder{color:#8e8e93}\n#v_sub input:focus,#v_sub select:focus{border-color:var(--mA)!important;box-shadow:0 0 0 4px rgba(10,108,255,.14)!important}\n/* table */\n#v_sub .scroll{background:var(--mCard)!important;border:1px solid var(--mLine)!important;border-radius:20px!important;box-shadow:0 1px 2px rgba(0,0,0,.03),0 10px 28px -16px rgba(20,30,60,.16)!important;padding:4px!important}\n#v_sub #t_sub{color:var(--mInk)!important;border-collapse:separate;border-spacing:0}\n#v_sub #t_sub thead th{background:#f5f5f7!important;color:var(--mMut)!important;font-size:12.5px;font-weight:600;text-transform:none;border-bottom:1px solid var(--mLine)!important}\n#v_sub #t_sub td{border-bottom:1px solid #f0f0f4!important}\n#v_sub #t_sub tbody tr:hover td{background:#f8faff}\n#v_sub #myDuty{background:#fff8e6!important;color:#5c3b00!important;border:1px solid #ffe2a8!important;border-radius:18px!important;box-shadow:none!important}\n#v_sub .pbtn{border-radius:10px!important}\n#v_sub a{color:var(--mA)}\n/* duplicate buttons removed from the page body (the same actions live in the \"Actions\" menu / toolbar) */\n#v_sub .subModes .subMini,#v_sub .subModes .dlBar,#v_sub .sndBtn,#v_sub .saBtn{display:none!important}\n";document.head.append(st)}catch(e){}})();

